WITH valid AS (SELECT *, CASE WHEN discount >= 0.44 THEN 'High' WHEN discount >= 0.19 THEN 'Medium' ELSE 'Low' END AS discount_band, TRIM(status) AS clean_status FROM orders WHERE order_date >= DATE '2023-06-19'), latest_match AS (SELECT s.*, top1.payment_status, top1.payment_method FROM valid s LEFT JOIN LATERAL (SELECT c.status AS payment_status, c.method AS payment_method FROM payments c WHERE c.order_id = s.id ORDER BY c.amount DESC, c.id DESC LIMIT 1) top1 ON TRUE), enriched AS (SELECT a.*, b.opened_date, b.city, b.store_name FROM latest_match a LEFT JOIN stores b ON a.store_id = b.id), with_last AS (SELECT s.*, top1.carrier FROM enriched s LEFT JOIN LATERAL (SELECT c.carrier FROM shipments c WHERE c.order_id = s.id ORDER BY c.cost DESC, c.id DESC LIMIT 1) top1 ON TRUE), matched AS (SELECT s.*, pr.id AS promo_id, pr.promo_code, pr.discount_pct FROM with_last s LEFT JOIN promotions pr ON COALESCE(s.channel, 'store') = pr.channel AND s.order_date BETWEEN pr.starts_on AND pr.ends_on), kept_keys AS (SELECT store_id FROM matched EXCEPT SELECT store_id FROM orders WHERE store_id IS NOT NULL), kept_rows AS (SELECT s.* FROM matched s INNER JOIN kept_keys k ON s.store_id = k.store_id), grouped AS (SELECT CASE WHEN shipping_fee >= 37 THEN 'HIGH' ELSE 'LOW' END AS shipping_fee_tier, DATE_TRUNC('YEAR', opened_date) AS year_start, SORT_ARRAY(COLLECT_SET(payment_status)) AS payment_status_list, SIZE(COLLECT_SET(city)) AS num_cities, APPROX_PERCENTILE(shipping_fee, 0.9) AS shipping_fee_p90, GROUPING_ID() AS gid FROM kept_rows GROUP BY GROUPING SETS ((CASE WHEN shipping_fee >= 37 THEN 'HIGH' ELSE 'LOW' END, DATE_TRUNC('YEAR', opened_date)), (CASE WHEN shipping_fee >= 37 THEN 'HIGH' ELSE 'LOW' END), ())) SELECT year_start, payment_status_list, num_cities, shipping_fee_p90 FROM grouped ORDER BY year_start DESC;
